sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    //this BR makes an API call using Rest Message MSS Outbound Send GCP to get payload
    try {
        var api_flag = gs.getProperty('x_hsb11_hsbc_mss_o.eventOutbound_GCP_HSS');
        var restMessage;
        current.state = "Processing";
        current.request_date = new GlideDateTime();
        current.update();
        if (api_flag == 'GCP') {
            var gcpOutboundToken = gs.getProperty('x_hsb11_hsbc_mss_o.eventOutbound_GCP_token');
            var gcpPayloadURL = gs.getProperty('x_hsb11_hsbc_mss_o.eventOutbound_GCP_uri_payload');
            restMessage = new sn_ws.RESTMessageV2('MSS Outbound Send GCP', 'payloadAPI');
            restMessage.setStringParameterNoEscape('eventoutbound_base_uri', gcpPayloadURL);
			//MSSRBXCE-518 Setting Authorization and Content-Type Headers 
			restMessage.setRequestHeader('Authorization', 'Bearer ' + gcpOutboundToken );
			restMessage.setRequestHeader('Content-Type','application/x-www-form-urlencoded');
			//MSSRBXCE-518 Extracting source and messageId from request_body field
			var regex = /^(.*?)source=([\w]+)&messageId=([\w_]+)\s*$/;
			var match = current.request_body.match(regex);
			var source,messageId;

			//MSSRBXCE-563 Added if else condition here to trigger error 400 if the mandatory felids are missing
			if(match==null)
			{
				source = '';
				messageId = '';
			}
			else
			{
				source = match[2];
				messageId = match[3];
			}

			//MSSRBXCE-518 Setting source and messageId as request body
			var requestBody = 'source='+source+'&messageId='+messageId;
			restMessage.setRequestBody(requestBody);
        } else {
			var RequestBody = current.request_body;
            var mssOutboundToken = gs.getProperty('x_hsb11_hsbc_mss_o.hsbcmss_EventLayerOutbound_api_token');
            var eventOutboundenv = gs.getProperty('x_hsb11_hsbc_mss_o.eventOutbound_uri');
            restMessage = new sn_ws.RESTMessageV2('MSS Outbound Send', 'Default GET');
            restMessage.setStringParameterNoEscape('mssOutbound_token', mssOutboundToken);
            restMessage.setStringParameterNoEscape('eventoutbound_base_uri', eventOutboundenv);
			restMessage.setStringParameterNoEscape('requestbody', RequestBody);
        }

        restMessage.setEccCorrelator(current.sys_id);
        restMessage.executeAsync();
    } catch (ex) {
        var message = ex.message;
        current.error_body = message;
        current.state = "Error";
        current.update();
    }
})(current, previous);
